from collections import Counter
def transform(g):
    R,C=len(g),len(g[0])
    ones=[(r,c) for r in range(R) for c in range(C) if g[r][c]==1]
    r0,r1=min(r for r,_ in ones),max(r for r,_ in ones)
    c0,c1=min(c for _,c in ones),max(c for _,c in ones)
    dots={}; colored={}
    for r in range(R):
        for c in range(C):
            v=g[r][c]
            if v in (0,1): continue
            if r0<=r<=r1 and c0<=c<=c1: colored.setdefault(v,[]).append((r,c))
            else: dots.setdefault(v,[]).append((r,c))
    sols=[]
    for v,ds in dots.items():
        for d in ds:
            for p in colored[v]:
                sols.append((d[0]+p[1], d[1]+p[0]))  # A=dr+c, B=dc+r
    (A,B),_=Counter(sols).most_common(1)[0]
    pts=[(A-c,B-r,g[r][c]) for r in range(r0,r1+1) for c in range(c0,c1+1) if g[r][c]!=1]
    dr0=min(r for v in dots.values() for r,_ in v)-1
    dr1=max(r for v in dots.values() for r,_ in v)+1
    dc0=min(c for v in dots.values() for _,c in v)-1
    dc1=max(c for v in dots.values() for _,c in v)+1
    H,W=dr1-dr0+1, dc1-dc0+1
    out=[[1]*W for _ in range(H)]
    for gr,gc,v in pts:
        out[gr-dr0][gc-dc0]=v
    return out

